package ma.lias.entity;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="events")
public class Event { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private String title; @Enumerated(EnumType.STRING) private EventType type; @Column(length=4000) private String description; @Column(name="start_date") private LocalDateTime startDate; @Column(name="end_date") private LocalDateTime endDate; private String location; @Column(name="organizer_id") private Long organizerId; private String edition; private boolean archived; public Long getId(){return id;} public void setId(Long id){this.id=id;} public String getTitle(){return title;} public void setTitle(String title){this.title=title;} public EventType getType(){return type;} public void setType(EventType type){this.type=type;} public String getDescription(){return description;} public void setDescription(String description){this.description=description;} public LocalDateTime getStartDate(){return startDate;} public void setStartDate(LocalDateTime startDate){this.startDate=startDate;} public LocalDateTime getEndDate(){return endDate;} public void setEndDate(LocalDateTime endDate){this.endDate=endDate;} public String getLocation(){return location;} public void setLocation(String location){this.location=location;} public Long getOrganizerId(){return organizerId;} public void setOrganizerId(Long organizerId){this.organizerId=organizerId;} public String getEdition(){return edition;} public void setEdition(String edition){this.edition=edition;} public boolean isArchived(){return archived;} public void setArchived(boolean archived){this.archived=archived;} }
